<?php
if(session_status()===PHP_SESSION_NONE)session_start();require_once '../includes/config.php';require_once '../includes/database.php';require_once '../includes/auth.php';$db=new Database();$auth=new Auth($db);$auth->requireRole('passenger');$pdo=$db->getConnection();$stmt=$pdo->prepare("SELECT b.baggage_code,b.status,b.weight,b.created_at,f.flight_number,f.departure_time,f.arrival_time FROM baggage b JOIN flights f ON b.flight_id=f.id WHERE b.passenger_id=? ORDER BY f.departure_time DESC");$stmt->execute([$auth->getUserId()]);$rows=$stmt->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>History</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body><div class="container py-5"><a href="dashboard.php">← Dashboard</a><h2>Travel & Baggage History</h2><div class="table-responsive"><table class="table table-striped"><thead><tr><th>Flight</th><th>Baggage</th><th>Status</th><th>Weight</th><th>Departure</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=htmlspecialchars($r['flight_number'])?></td><td><?=htmlspecialchars($r['baggage_code'])?></td><td><?=htmlspecialchars($r['status'])?></td><td><?=htmlspecialchars($r['weight'])?></td><td><?=htmlspecialchars($r['departure_time'])?></td></tr><?php endforeach;?></tbody></table></div></div></body></html>